'use strict';

// MODULES //

var ndarraylike2scalar = require( '@stdlib/ndarray-base-ndarraylike2scalar' );
var numelDimension = require( '@stdlib/ndarray-base-numel-dimension' );
var clipUpperIndex = require( '@stdlib/ndarray-base-clip-upper-index' );
var getStride = require( '@stdlib/ndarray-base-stride' );
var getOffset = require( '@stdlib/ndarray-base-offset' );
var getData = require( '@stdlib/ndarray-base-data-buffer' );
var strided = require( '@stdlib/blas-ext-base-gfind-last-index' ).ndarray;


// MAIN //

/**
* Returns the index of the last element in a one-dimensional ndarray which passes a test implemented by a predicate function within a specified range.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray containing the index from which to begin searching.
*     -   a zero-dimensional ndarray containing the index at which to stop searching (exclusive).
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @param {Function} clbk - callback function
* @param {*} [thisArg] - callback execution context
* @returns {integer} index
*
* @example
* var scalar2ndarray = require( '@stdlib/ndarray-from-scalar' );
* var vector = require( '@stdlib/ndarray-vector-ctor' );
*
* function clbk( v ) {
*     return v % 2.0 === 0.0;
* }
*
* var x = vector( [ 2.0, 1.0, 3.0, 4.0, 5.0 ], 'generic' );
*
* var fromIndex = scalar2ndarray( 4, {
*     'dtype': 'generic'
* });
*
* var toIndex = scalar2ndarray( 1, {
*     'dtype': 'generic'
* });
*
* var v = gfindLastIndexBetween( [ x, fromIndex, toIndex ], clbk );
* // returns 3
*/
function gfindLastIndexBetween( arrays, clbk, thisArg ) {
	var fromIndex;
	var toIndex;
	var stride;
	var offset;
	var idx;
	var N;
	var n;
	var x;

	x = arrays[ 0 ];
	fromIndex = ndarraylike2scalar( arrays[ 1 ] );
	toIndex = ndarraylike2scalar( arrays[ 2 ] );

	N = numelDimension( x, 0 );
	fromIndex = clipUpperIndex( fromIndex, ( fromIndex < 0 ) ? N : N-1 );
	if ( fromIndex < 0 ) {
		return -1;
	}
	toIndex = clipUpperIndex( toIndex, ( toIndex < 0 ) ? N : N-1 );

	n = fromIndex - toIndex;
	if ( n <= 0 ) {
		return -1;
	}
	stride = getStride( x, 0 );
	offset = getOffset( x ) + ( stride*( toIndex+1 ) );

	idx = strided( n, getData( x ), stride, offset, wrapper, null );
	if ( idx >= 0 ) {
		idx += toIndex+1;
	}
	return idx;

	/**
	* Invokes a provided callback.
	*
	* @private
	* @param {*} value - current array element
	* @param {NonNegativeInteger} aidx - current array element index
	* @param {NonNegativeInteger} sidx - current strided array element index
	* @param {Collection} arr - input array
	* @returns {*} result
	*/
	function wrapper( value, aidx ) {
		return clbk.call( thisArg, value, fromIndex - aidx, x );
	}
}


// EXPORTS //

module.exports = gfindLastIndexBetween;
